from datetime import date, datetime, timedelta
import json
import random

import pandas as pd

import calendar_export
import categories
import config
import database
import importers


def _course_rows(anchor):
    """Return forty weekly courses spanning exactly twelve complete weeks."""
    first = anchor - timedelta(weeks=config.HISTORY_WEEKS)
    last = anchor + timedelta(weeks=config.FUTURE_WEEKS) - timedelta(days=1)
    rows = []
    for index, title in enumerate(config.DEMO_COURSES):
        weekday = index % 5 if index < config.DEMO_WEEKDAY_COURSES else 5 + index % 2
        start, end = config.DEMO_COURSE_TIMES[index % len(config.DEMO_COURSE_TIMES)]
        if title == 'Fitness Late':
            start, end = '21:00', '22:30'
        rows.append({'course_id': f'demo-sport-{index:02d}', 'sport': title, 'title': title,
                     'level': 'Intermediate' if 'Intermediate' in title else 'All levels',
                     'weekday': config.DEMO_WEEKDAY_NAMES[weekday],
                     'start_time': start, 'end_time': end,
                     'location': config.DEMO_SPORT_LOCATIONS[
                         index % len(config.DEMO_SPORT_LOCATIONS)],
                     'valid_from': first.isoformat(), 'valid_to': last.isoformat(),
                     'source_url': config.UNISPORT_URL, 'registration_url': config.UNISPORT_URL,
                     'description': 'Illustrative demo course, not a live timetable.',
                     'price_chf': '20.00' if title in ('Climbing', 'Bouldering') else '0'})
    return rows


def _demo_start(anchor, index, count, hour):
    """Spread dated fixtures over the configured history/future window."""
    days = (config.HISTORY_WEEKS + config.FUTURE_WEEKS) * config.DAYS_PER_WEEK
    day = anchor - timedelta(weeks=config.HISTORY_WEEKS) + timedelta(days=index * days // count)
    return datetime.combine(day, datetime.min.time()) + timedelta(hours=hour)


def _club_rows(anchor, rng):
    """Generate sixty club events with varied status, location and end availability."""
    rows = []
    for index in range(config.DEMO_CLUB_COUNT):
        name, category, title = config.DEMO_CLUBS[index % len(config.DEMO_CLUBS)]
        start = _demo_start(anchor, index, config.DEMO_CLUB_COUNT, 18 + index % 3)
        end = start + timedelta(minutes=config.DEFAULT_DURATION_MINUTES)
        event_type = 'Workshop' if 'workshop' in title else 'Talk'
        location = config.DEMO_CLUB_LOCATIONS[index % len(config.DEMO_CLUB_LOCATIONS)]
        if index in (17, 37, 57):
            event_type, location, end = 'Trip', 'Prague', start + timedelta(days=2)
        elif category == 'Social':
            event_type = 'Social'
        status = 'OPEN'
        if index in config.DEMO_FULL_INDICES:
            status = 'FULL'
        elif index in config.DEMO_CLOSED_INDICES:
            status = 'CLOSED'
        elif index % 11 == 0:
            status = 'APPLY'
        elif index % 13 == 0:
            status = 'Members Only'
        missing = index < config.DEMO_MISSING_END_COUNT and event_type != 'Trip'
        rows.append({'id': f'demo-club-{index:02d}', 'title': title,
                     'club': {'name': name, 'category': category}, 'start': start.isoformat(),
                     'end': None if missing else end.isoformat(), 'location': location,
                     'type': event_type, 'status': status, 'members_only': status == 'Members Only',
                     'description': 'Demo event; check the organizer for real offerings.',
                     'price': '0' if index % 2 == 0 else rng.choice(config.DEMO_PRICES[1:]),
                     'url': '', 'registration_url': ''})
    return rows


def _city_rows(anchor, rng):
    """Generate thirty dated city events with explicit end times."""
    rows = []
    for index in range(config.DEMO_CITY_COUNT):
        title, venue = config.DEMO_CITY_EVENTS[index % len(config.DEMO_CITY_EVENTS)]
        start = _demo_start(anchor, index, config.DEMO_CITY_COUNT, 19)
        rows.append({'id': f'demo-city-{index:02d}', 'title': title, 'organizer': venue,
                     'start': start.isoformat(), 'end': (start + timedelta(hours=2)).isoformat(),
                     'location': venue,
                     'description': 'Illustrative city event, not a live listing.',
                     'price': rng.choice(config.DEMO_PRICES), 'type': '', 'status': 'OPEN',
                     'url': '', 'registration_url': ''})
    return rows


def write_placeholder_sources(anchor_date, sources_dir=config.SOURCES_DIR):
    """Write deterministic Excel and JSON source fixtures for one anchor week."""
    anchor = anchor_date - timedelta(days=anchor_date.weekday())
    sources_dir.mkdir(parents=True, exist_ok=True)
    # Course: U02 s5 – keep the random generator private and seeded.
    rng = random.Random(config.RANDOM_SEED)
    paths = {}
    for source in config.SOURCES:
        paths[source] = sources_dir / config.PLACEHOLDER_NAMES[source]
    pd.DataFrame(_course_rows(anchor)).to_excel(paths['unisport'], index=False)
    for source, rows in (('uniclubs', _club_rows(anchor, rng)), ('city', _city_rows(anchor, rng))):
        payload = {'_meta': {'ai_citation': config.DEMO_CITATION, 'is_placeholder': True},
                   'events': rows}
        text = json.dumps(payload, ensure_ascii=False, indent=2)
        paths[source].write_text(text, encoding='utf-8')
    return paths


def _calendar_entry(uid, day, start_text, end_text, title, repeating=False, transparent=False):
    """Write one demo VEVENT in Zurich local time so weekly recurrences survive DST correctly."""
    start = datetime.combine(day, datetime.strptime(start_text, config.SOURCE_TIME_FORMAT).time())
    end = datetime.combine(day, datetime.strptime(end_text, config.SOURCE_TIME_FORMAT).time())
    lines = ['BEGIN:VEVENT', f'UID:demo-{uid}@weekwise',
             f'DTSTART;TZID={config.TIMEZONE_NAME}:{start:{config.ICS_LOCAL_FORMAT}}',
             f'DTEND;TZID={config.TIMEZONE_NAME}:{end:{config.ICS_LOCAL_FORMAT}}',
             f'SUMMARY:{calendar_export.escape_ics_text(title)}']
    if repeating:
        count = config.HISTORY_WEEKS + config.FUTURE_WEEKS
        lines.append(f'RRULE:FREQ=WEEKLY;COUNT={count}')
    if transparent:
        lines.append('TRANSP:TRANSPARENT')
    return lines + ['END:VEVENT']


def write_demo_calendar(anchor_date, path=config.DEMO_CALENDAR_FILE):
    """Write the reproducible HSG calendar from SPEC section 17.4 without an ICS writing library.

    :param anchor_date: date in the anchor week
    :param path: output path; tests supply an isolated temporary path
    :return: path of the generated UTF-8 calendar
    """
    anchor = anchor_date - timedelta(days=anchor_date.weekday())
    beginning = anchor - timedelta(weeks=config.HISTORY_WEEKS)
    lines = ['BEGIN:VCALENDAR', 'VERSION:2.0', f'PRODID:{config.ICS_PRODID}', 'CALSCALE:GREGORIAN']
    for index, (weekday, start, end, title) in enumerate(config.DEMO_WEEKLY_CALENDAR):
        lines.extend(_calendar_entry(f'weekly-{index}', beginning + timedelta(days=weekday),
                                     start, end, title, repeating=True))
    for index, (offset, start, end, title, transparent) in enumerate(config.DEMO_CALENDAR_ONE_OFFS):
        lines.extend(_calendar_entry(f'oneoff-{index}', anchor + timedelta(days=offset),
                                     start, end, title, transparent=transparent))
    birthday = anchor + timedelta(days=config.DEMO_BIRTHDAY_WEEKDAY)
    lines.extend(['BEGIN:VEVENT', 'UID:demo-birthday@weekwise',
                  f'DTSTART;VALUE=DATE:{birthday:{config.ICS_DATE_FORMAT}}',
                  f'DTEND;VALUE=DATE:{birthday + timedelta(days=1):{config.ICS_DATE_FORMAT}}',
                  f'SUMMARY:{calendar_export.escape_ics_text(config.DEMO_BIRTHDAY_TITLE)}',
                  'END:VEVENT', 'END:VCALENDAR'])
    text = '\r\n'.join(calendar_export.fold_ics_line(line) for line in lines) + '\r\n'
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(text.encode('utf-8'))
    return path


def ensure_demo_calendar(connection, path=config.DEMO_CALENDAR_FILE, now=None):
    """Add the M2 calendar to an existing M1 database without resetting its source data."""
    if not path.exists():
        anchor = database.get_setting(connection, 'demo_anchor_date')
        day = date.fromisoformat(anchor) if anchor else config.local_now(now).date()
        write_demo_calendar(day, path)


def generate_all(connection, anchor_date=None, sources_dir=config.SOURCES_DIR,
                 snapshot_dir=config.SNAPSHOT_DIR, private_file=config.PRIVATE_SOURCES_FILE):
    """Generate M1/M2 source fixtures and calendar; later user histories remain out of scope."""
    day = anchor_date if anchor_date is not None else config.local_now().date()
    anchor = day - timedelta(days=day.weekday())
    taxonomy = categories.load_taxonomy()
    categories.seed_categories(connection, taxonomy)
    write_placeholder_sources(anchor, sources_dir)
    write_demo_calendar(anchor, sources_dir.parent / 'demo' / config.DEMO_CALENDAR_FILE.name)
    reports = importers.import_all(connection, taxonomy, include_past=True,
                                   sources_dir=sources_dir, snapshot_dir=snapshot_dir,
                                   private_file=private_file)
    if any(report['outcome'] != 'ok' for report in reports):
        raise ValueError('Demo setup could not import every source. Check your source files.')
    database.set_setting(connection, 'demo_anchor_date', anchor.isoformat())
    database.set_setting(connection, 'setup_done', '1')
    return reports


if __name__ == '__main__':
    db = database.get_connection()
    try:
        database.init_db(db)
        for report in generate_all(db):
            print(report)
    finally:
        db.close()
